import{_ as i,o as a,c as t,a2 as e}from"./chunks/framework.Wk4ah3nE.js";const k=JSON.parse('{"title":"Notifications","description":"Configure Gotify push and SMTP email notifications for Proxmox VM Autoscale, including when they fire, what priority each event carries, and how failures are handled.","frontmatter":{"title":"Notifications","description":"Configure Gotify push and SMTP email notifications for Proxmox VM Autoscale, including when they fire, what priority each event carries, and how failures are handled.","head":[["link",{"rel":"canonical","href":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/notifications.html"}],["meta",{"property":"og:url","content":"https://fabriziosalmi.github.io/proxmox-vm-autoscale/guide/notifications.html"}],["meta",{"property":"og:title","content":"Notifications"}],["meta",{"property":"og:description","content":"Configure Gotify push and SMTP email notifications for Proxmox VM Autoscale, including when they fire, what priority each event carries, and how failures are handled."}]]},"headers":[],"relativePath":"guide/notifications.md","filePath":"guide/notifications.md","lastUpdated":null}'),n={name:"guide/notifications.md"};function l(o,s,h,p,r,d){return a(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="notifications" tabindex="-1">Notifications <a class="header-anchor" href="#notifications" aria-label="Permalink to &quot;Notifications&quot;">​</a></h1><p>Two independent channels: <strong>Gotify</strong> push and <strong>SMTP</strong> email. Enable either, both, or neither. Configuration is validated at startup, so a broken notification setup stops the service immediately rather than failing quietly the first time something interesting happens.</p><h2 id="when-notifications-fire" tabindex="-1">When notifications fire <a class="header-anchor" href="#when-notifications-fire" aria-label="Permalink to &quot;When notifications fire&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Event</th><th>Priority</th><th>Sent</th></tr></thead><tbody><tr><td>CPU or RAM scaled <strong>up</strong></td><td>7</td><td>Only when the resource actually changed</td></tr><tr><td>CPU or RAM scaled <strong>down</strong></td><td>5</td><td>Only when the resource actually changed</td></tr><tr><td>Error processing a VM</td><td>9</td><td>Every occurrence</td></tr><tr><td>Unexpected error in the main loop</td><td>10</td><td>Every occurrence, then 60 s pause</td></tr></tbody></table><p>Nothing is sent for a routine poll, and nothing is sent when a threshold is crossed but no change results — hitting <code>max_cores</code>, or being inside a cooldown, is silent. Priority is a Gotify concept; the SMTP channel ignores it.</p><div class="tip custom-block"><p class="custom-block-title">Error notifications can be a firehose</p><p>A node that has become unreachable produces a priority-9 notification <strong>per VM, per cycle</strong>. Twenty VMs on a 300-second interval is 240 notifications an hour. There is no rate limiting or deduplication. Consider Gotify-side filtering if this matters to you.</p></div><h2 id="gotify" tabindex="-1">Gotify <a class="header-anchor" href="#gotify" aria-label="Permalink to &quot;Gotify&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">gotify</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  server_url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://gotify.example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  app_token</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">AbCdEf123456789</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  priority</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>yes</td><td><code>false</code> disables the channel entirely</td></tr><tr><td><code>server_url</code></td><td>when enabled</td><td>Base URL. A trailing slash is stripped for you</td></tr><tr><td><code>app_token</code></td><td>when enabled</td><td><strong>Application</strong> token, not a client token</td></tr><tr><td><code>priority</code></td><td>no</td><td>Default priority; per-event values above override it</td></tr></tbody></table><p>Messages <code>POST</code> to <code>{server_url}/message</code> with a 10-second timeout, <code>Authorization: Bearer &lt;app_token&gt;</code>, and the title <code>VM Autoscale Alert</code>.</p><p>If <code>enabled: true</code> and either <code>server_url</code> or <code>app_token</code> is missing, startup fails with:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ConfigurationError: Gotify is enabled but configuration is incomplete</span></span></code></pre></div><h3 id="getting-a-token" tabindex="-1">Getting a token <a class="header-anchor" href="#getting-a-token" aria-label="Permalink to &quot;Getting a token&quot;">​</a></h3><p>In Gotify: <strong>Apps → Create Application</strong>, then copy the token shown. Verify it out of band before wiring it in:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;https://gotify.example.com/message&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Authorization: Bearer AbCdEf123456789&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;title=test&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;message=hello&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -F</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;priority=5&quot;</span></span></code></pre></div><h2 id="email-smtp" tabindex="-1">Email (SMTP) <a class="header-anchor" href="#email-smtp" aria-label="Permalink to &quot;Email (SMTP)&quot;">​</a></h2><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">alerts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  email_enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  email_recipient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ops@example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  smtp_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">smtp.example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  smtp_port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">587</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  smtp_user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">autoscale@example.com</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  smtp_password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">your_smtp_password</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Key</th><th>Required</th><th>Notes</th></tr></thead><tbody><tr><td><code>email_enabled</code></td><td>yes</td><td></td></tr><tr><td><code>smtp_server</code></td><td>when enabled</td><td>Validated at startup</td></tr><tr><td><code>smtp_user</code></td><td>when enabled</td><td>Also used as the <code>From</code> address</td></tr><tr><td><code>email_recipient</code></td><td>when enabled</td><td>A string, or a list of strings for several recipients</td></tr><tr><td><code>smtp_port</code></td><td>no</td><td>Defaults to <code>587</code></td></tr><tr><td><code>smtp_password</code></td><td>no</td><td><strong>Leave empty to skip <code>login()</code></strong> — for relays that authenticate by IP</td></tr></tbody></table><p>The service always calls <code>starttls()</code>, then authenticates only if <code>smtp_password</code> is non-empty.</p><h3 id="subject-lines" tabindex="-1">Subject lines <a class="header-anchor" href="#subject-lines" aria-label="Permalink to &quot;Subject lines&quot;">​</a></h3><p>The VMID is extracted from the message body with the pattern <code>VM\\s+(\\d+)</code>, producing:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Subject: VM Autoscale Alert for VM 101</span></span></code></pre></div><p>Messages with no VMID in them — most main-loop errors — get <code>VM Autoscale Alert for VM </code> with a trailing space. Cosmetic, but it makes subject-based mail filters unreliable for those.</p><h3 id="several-recipients" tabindex="-1">Several recipients <a class="header-anchor" href="#several-recipients" aria-label="Permalink to &quot;Several recipients&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">alerts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  email_recipient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ops@example.com</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">oncall@example.com</span></span></code></pre></div><h3 id="local-relay" tabindex="-1">Local relay <a class="header-anchor" href="#local-relay" aria-label="Permalink to &quot;Local relay&quot;">​</a></h3><p>If the host already has a working MTA:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">alerts</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  email_enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  smtp_server</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">localhost</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  smtp_port</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">25</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  smtp_user</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">vm-autoscale@$(hostname -f)</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  smtp_password</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  email_recipient</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">root@example.com</span></span></code></pre></div><p>Note <code>starttls()</code> is called unconditionally, so a relay on port 25 must advertise STARTTLS. A plain-text-only local relay will fail.</p><h2 id="failure-handling" tabindex="-1">Failure handling <a class="header-anchor" href="#failure-handling" aria-label="Permalink to &quot;Failure handling&quot;">​</a></h2><p>Channels are attempted independently and a failure in one does not block the other. Failures are logged, not retried, and never crash the service:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ERROR] Failed to send Gotify notification: HTTPSConnectionPool(...): Read timed out.</span></span></code></pre></div><p>If every configured channel fails, the message itself is written to the log so it is not lost:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[WARNING] Failed to send notification through any channel.</span></span>
<span class="line"><span>          Message: Scaled up CPU for VM 101 due to high usage (91.2%).</span></span>
<span class="line"><span>          Errors: Failed to send Gotify notification: ...</span></span></code></pre></div><p>With no channel enabled at all, you get one warning at startup and then silence:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[WARNING] No notification method is enabled in configuration</span></span></code></pre></div><h2 id="verifying-without-waiting-for-load" tabindex="-1">Verifying without waiting for load <a class="header-anchor" href="#verifying-without-waiting-for-load" aria-label="Permalink to &quot;Verifying without waiting for load&quot;">​</a></h2><p>Temporarily set an impossible threshold, run the service in the foreground for one cycle, and put it back:</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">scaling_thresholds</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  cpu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    high</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    low</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span></span></code></pre></div><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stop</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vm_autoscale.service</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python3</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/local/bin/vm_autoscale/autoscale.py</span></span></code></pre></div><h2 id="security-notes" tabindex="-1">Security notes <a class="header-anchor" href="#security-notes" aria-label="Permalink to &quot;Security notes&quot;">​</a></h2><p><code>smtp_password</code> and <code>app_token</code> sit in plain text in <code>config.yaml</code>. That file must be mode <code>600</code> and root-owned — the installer does this, and the <a href="/proxmox-vm-autoscale/security/hardening.html">hardening guide</a> covers verifying it. Notification bodies contain VMIDs, host names and usage figures; treat your Gotify server and mail path as carrying operational detail about your infrastructure.</p>`,42)])])}const g=i(n,[["render",l]]);export{k as __pageData,g as default};
